import{_ as l,r as n,o as r,c as d,e as a,a as t,s}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Rich Editor / WYSIWYG Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Rich Editor / WYSIWYG"},"headers":[{"level":2,"title":"Toolbar Definitions","slug":"toolbar-definitions","link":"#toolbar-definitions","children":[{"level":3,"title":"Registering a Toolbar Definition","slug":"registering-a-toolbar-definition","link":"#registering-a-toolbar-definition","children":[]}]},{"level":2,"title":"Toolbar Precedence","slug":"toolbar-precedence","link":"#toolbar-precedence","children":[]},{"level":2,"title":"Registering a Custom Button","slug":"registering-a-custom-button","link":"#registering-a-custom-button","children":[{"level":3,"title":"The Editor Instance","slug":"the-editor-instance","link":"#the-editor-instance","children":[]},{"level":3,"title":"Trigger a Modal from a Custom Button","slug":"trigger-a-modal-from-a-custom-button","link":"#trigger-a-modal-from-a-custom-button","children":[]}]},{"level":2,"title":"Advanced Editor Options","slug":"advanced-editor-options","link":"#advanced-editor-options","children":[{"level":3,"title":"Image Options","slug":"image-options","link":"#image-options","children":[]},{"level":3,"title":"File Upload Options","slug":"file-upload-options","link":"#file-upload-options","children":[]},{"level":3,"title":"Drag and Drop","slug":"drag-and-drop","link":"#drag-and-drop","children":[]},{"level":3,"title":"Where to find the full list","slug":"where-to-find-the-full-list","link":"#where-to-find-the-full-list","children":[]},{"level":3,"title":"Example: block all image insertion","slug":"example-block-all-image-insertion","link":"#example-block-all-image-insertion","children":[]}]}],"relativePath":"4.x/element/form/widget-richeditor.md","filePath":"4.x/element/form/widget-richeditor.md"}'),p={name:"4.x/element/form/widget-richeditor.md"};function c(u,e,g,h,k,f){const o=n("pre-heading"),i=n("post-heading");return r(),d("div",null,[a(o),e[0]||(e[0]=t("h1",null,"Rich Editor / WYSIWYG Field",-1)),a(i),e[1]||(e[1]=s(`<p><code>richeditor</code> - renders a visual editor for rich formatted text, also known as a WYSIWYG editor.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">html_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Contents
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>toolbar</strong></td><td>reference a named toolbar definition by its code. Example: <code>shop-content</code></td></tr><tr><td><strong>toolbarButtons</strong></td><td>buttons to show on the editor toolbar. Example: \`bold</td></tr><tr><td><strong>size</strong></td><td>specifies a field size for fields that use it, for example, the textarea field. Options: <code>tiny</code>, <code>small</code>, <code>large</code>, <code>huge</code>, <code>giant</code>.</td></tr><tr><td><strong>showMargins</strong></td><td>set to <code>true</code> to include resizable document margins. Default: <code>false</code>.</td></tr><tr><td><strong>useLineBreaks</strong></td><td>uses line breaks instead of paragraph wrappers for each new line. Default <code>false</code>.</td></tr><tr><td><strong>editorOptions</strong></td><td>custom editor options used by the editor control as an array (advanced).</td></tr></tbody></table></div><p>You may specify how large the field size should be with the <code>size</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">html_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Contents
    <span class="token key atrule">size</span><span class="token punctuation">:</span> huge
</code></pre></div><p>Use the <code>toolbarButtons</code> property to specify custom buttons.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">html_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Contents
    <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> bold<span class="token punctuation">|</span>italic<span class="token punctuation">|</span>underline
</code></pre></div><p>The double-pipe <code>||</code> character can be used to include a separator with the buttons.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> bold<span class="token punctuation">|</span>italic<span class="token punctuation">|</span>underline<span class="token punctuation">|</span><span class="token punctuation">|</span>insertPageLink<span class="token punctuation">|</span><span class="token punctuation">|</span>undo<span class="token punctuation">|</span>redo<span class="token punctuation">|</span><span class="token punctuation">|</span>clearFormatting
</code></pre></div><p>The available toolbar buttons are:</p>`,11)),e[2]||(e[2]=t("div",{class:"content-list",markdown:"1"},[t("ul",null,[t("li",null,"fullscreen"),t("li",null,"bold"),t("li",null,"italic"),t("li",null,"underline"),t("li",null,"strikeThrough"),t("li",null,"subscript"),t("li",null,"superscript"),t("li",null,"fontFamily"),t("li",null,"fontSize"),t("li",null,"color"),t("li",null,"emoticons"),t("li",null,"inlineStyle"),t("li",null,"paragraphStyle"),t("li",null,"paragraphFormat"),t("li",null,"align"),t("li",null,"formatOL"),t("li",null,"formatUL"),t("li",null,"outdent"),t("li",null,"indent"),t("li",null,"quote"),t("li",null,"insertHR"),t("li",null,"insertLink"),t("li",null,"insertPageLink"),t("li",null,"insertImage"),t("li",null,"insertVideo"),t("li",null,"insertAudio"),t("li",null,"insertFile"),t("li",null,"insertTable"),t("li",null,"insertSnippet"),t("li",null,"undo"),t("li",null,"redo"),t("li",null,"clearFormatting"),t("li",null,"selectAll"),t("li",null,"html")])],-1)),e[3]||(e[3]=s(`<div class="custom-block tip"><p>The <code>|</code> character will insert a vertical separator line in the toolbar.</p></div><h2 id="toolbar-definitions"><a href="#toolbar-definitions" class="header-anchor">#</a> Toolbar Definitions</h2><p>Toolbar definitions are named button configurations that can be shared by many rich editor fields and managed visually in the <strong>Settings → Editor Settings → Toolbar Buttons</strong> area. Each definition has a unique code, a label and a description explaining where it is used. Definitions are edited with a visual builder by dragging buttons between the toolbar and the available buttons palette.</p><p>The following definitions are included by default.</p><div class="table"><table tabindex="0"><thead><tr><th>Code</th><th>Description</th></tr></thead><tbody><tr><td><strong>default</strong></td><td>used by rich editors without a specific toolbar.</td></tr><tr><td><strong>minimal</strong></td><td>a compact toolbar for simple content.</td></tr><tr><td><strong>full</strong></td><td>every available button.</td></tr></tbody></table></div><p>Use the <code>toolbar</code> property to reference a definition from a rich editor field. The same code can be shared by any number of fields, and updating the definition updates every field that references it.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">description</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">toolbar</span><span class="token punctuation">:</span> shop<span class="token punctuation">-</span>content
</code></pre></div><p>A definition with no buttons inherits the default toolbar. This makes it possible to give an area of the admin panel its own toolbar code without prescribing any buttons, the fields simply follow the default toolbar until the definition is customized. The visual builder displays the inherited buttons for empty definitions, and modifying them makes the definition independent from the default toolbar. Definitions that have been changed from their registered configuration display as modified, along with a <strong>Reset to Default</strong> option to restore them.</p><p>Administrators may also create their own definitions with new codes using the <strong>Create Toolbar</strong> button, which can then be referenced from form fields and blueprints in the same way.</p><h3 id="registering-a-toolbar-definition"><a href="#registering-a-toolbar-definition" class="header-anchor">#</a> Registering a Toolbar Definition</h3><p>Plugins register toolbar definitions using the <code>registerRichEditorToolbars</code> method of the <a href="./../../extend/system/plugins.html">plugin registration file</a>. Each definition supplies a label and a description, along with an optional button list.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerRichEditorToolbars</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;shop-content&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Shop Content&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Used by shop product and category descriptions.&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The definition above contains no buttons, so it inherits the default toolbar until an administrator customizes it. Specify the <code>buttons</code> value as a comma separated list to register an opinionated button set, which also acts as the baseline for the <strong>Reset to Default</strong> feature.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerRichEditorToolbars</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;shop-content&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Shop Content&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Used by shop product and category descriptions.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;buttons&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;paragraphFormat, bold, italic, |, insertImage, insertPageLink, html&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Registered definitions appear in the settings area automatically, where administrators can review and customize them. <a href="#registering-a-custom-button">Custom buttons</a> registered in JavaScript can be included in a definition by their registered name.</p><h2 id="toolbar-precedence"><a href="#toolbar-precedence" class="header-anchor">#</a> Toolbar Precedence</h2><p>The toolbar button list is resolved for each editor from the first available source.</p><ol><li>The field <code>toolbarButtons</code> property, used exactly as written.</li><li>The field <code>toolbar</code> property, resolved to its toolbar definition.</li><li>The <strong>default</strong> toolbar definition, when it has been customized.</li><li>The built-in default button list.</li></ol><p>Custom buttons registered with a <code>toolbar</code> placement (see below) are added to the default toolbar automatically, and the default definition in the settings area displays them in place. Modifying the default toolbar stores the visible buttons exactly, making the placed buttons real entries that can be moved or removed. Every other source is used verbatim, so include the custom button name in the toolbar definition to display it there.</p><h2 id="registering-a-custom-button"><a href="#registering-a-custom-button" class="header-anchor">#</a> Registering a Custom Button</h2><p>Custom toolbar buttons are registered in JavaScript using the <code>oc.richEditor.registerButton</code> function. The API is available on every backend page, even when no rich editor is present, and the definition is editor-agnostic, it is not coupled to the underlying editor engine.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>richEditor<span class="token punctuation">.</span><span class="token function">registerButton</span><span class="token punctuation">(</span><span class="token string">&#39;insertCustomThing&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">&#39;Insert Something&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">icon</span><span class="token operator">:</span> <span class="token string">&#39;icon-star&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">toolbar</span><span class="token operator">:</span> <span class="token string">&#39;end&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">undo</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
    <span class="token literal-property property">focus</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
    <span class="token function-variable function">onClick</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">editor</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        editor<span class="token punctuation">.</span><span class="token function">insertHtml</span><span class="token punctuation">(</span><span class="token string">&#39;&lt;strong&gt;My Custom Thing!&lt;/strong&gt;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Register the JavaScript globally on every backend page, so the button is available to every rich editor surface, including the form widget and the CMS editor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.page.beforeDisplay&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/october/test/assets/js/custom-button.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Call <code>registerButton</code> at the top level of your script, plain and module scripts both work. Do not wrap the call in <code>oc.pageReady()</code>. Registration must complete before the first editor on the page initializes, which is guaranteed for any script included in the page.</p></div><p>The following properties are supported by the button definition.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>the button tooltip and accessible label.</td></tr><tr><td><strong>icon</strong></td><td>an icon class name, for example <code>icon-star</code>, or custom markup as <code>{ html: &#39;&lt;svg&gt;...&lt;/svg&gt;&#39; }</code>.</td></tr><tr><td><strong>toolbar</strong></td><td>where to place the button: <code>start</code>, <code>end</code>, <code>{ before: &#39;name&#39; }</code> or <code>{ after: &#39;name&#39; }</code>. Omit to register the command without placing it.</td></tr><tr><td><strong>separator</strong></td><td>inserts a separator line next to the button: <code>before</code>, <code>after</code> or <code>both</code>.</td></tr><tr><td><strong>undo</strong></td><td>records an undo step after the button action. Default: <code>true</code>.</td></tr><tr><td><strong>focus</strong></td><td>focuses the editor before the button action. Default: <code>true</code>.</td></tr><tr><td><strong>onClick</strong></td><td>function called when the button is clicked, receives the editor instance.</td></tr></tbody></table></div><h3 id="the-editor-instance"><a href="#the-editor-instance" class="header-anchor">#</a> The Editor Instance</h3><p>The <code>onClick</code> function receives an editor object with the following methods, which remain stable across editor engine versions.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>insertHtml(html)</strong></td><td>inserts HTML at the cursor position.</td></tr><tr><td><strong>insertElement(element)</strong></td><td>inserts a DOM element or jQuery object.</td></tr><tr><td><strong>insertUiBlock(node)</strong></td><td>inserts a non-editable block element.</td></tr><tr><td><strong>getContent()</strong> / <strong>setContent(html)</strong></td><td>reads or replaces the document contents.</td></tr><tr><td><strong>saveSelection()</strong> / <strong>restoreSelection()</strong></td><td>preserves the selection around popups or dialogs.</td></tr><tr><td><strong>focus()</strong></td><td>focuses the editing surface.</td></tr><tr><td><strong>saveUndoStep()</strong></td><td>records an undo checkpoint.</td></tr><tr><td><strong>engine</strong></td><td>the active engine name, for advanced use.</td></tr><tr><td><strong>native</strong></td><td>the raw engine instance, engine-specific and subject to change.</td></tr></tbody></table></div><h3 id="trigger-a-modal-from-a-custom-button"><a href="#trigger-a-modal-from-a-custom-button" class="header-anchor">#</a> Trigger a Modal from a Custom Button</h3><p>Use the <code>oc.popup</code> JavaScript function to open a modal window.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">popup</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    <span class="token literal-property property">handler</span><span class="token operator">:</span> <span class="token string">&#39;onLoadPopup&#39;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>backend.ajax.beforeRunHandler</code> to register a global AJAX handler. The <code>makePartial</code> method can be called to render a partial with the modal contents inside.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.ajax.beforeRunHandler&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">,</span> <span class="token variable">$handler</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$handler</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;onLoadPopup&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;~/path/to/my/partials/_popup_form.php&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="advanced-editor-options"><a href="#advanced-editor-options" class="header-anchor">#</a> Advanced Editor Options</h2><p>Use the <code>editorOptions</code> property to customize the editor options. This is an advanced property, since all options defined here are proxied directly to the editor control.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">html_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">editorOptions</span><span class="token punctuation">:</span>
        <span class="token key atrule">imageDefaultWidth</span><span class="token punctuation">:</span> <span class="token number">0</span>
</code></pre></div><p>The options are proxied to the underlying Froala editor. The most commonly used options are listed below, grouped by area.</p><h3 id="image-options"><a href="#image-options" class="header-anchor">#</a> Image Options</h3><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>imageUpload</strong></td><td>Enables image uploads. Set to <code>false</code> to block users from inserting images via the upload button or by dropping image files into the editor. Default: <code>true</code>.</td></tr><tr><td><strong>imagePaste</strong></td><td>Allows pasting images from the clipboard. Set to <code>false</code> to strip pasted images. Default: <code>true</code>.</td></tr><tr><td><strong>imagePasteProcess</strong></td><td>When <code>true</code>, pasted images are re-uploaded through the configured upload handler instead of being kept as inline data. Default: <code>false</code>.</td></tr><tr><td><strong>imageMove</strong></td><td>Allows existing images inside the editor to be dragged to a new position. Set to <code>false</code> to lock images in place. Default: <code>true</code>.</td></tr><tr><td><strong>imageResize</strong></td><td>Allows images to be resized by dragging their corners. Set to <code>false</code> to disable resizing. Default: <code>true</code>.</td></tr><tr><td><strong>imageResizeWithPercent</strong></td><td>When <code>true</code>, image sizes are stored as percentages rather than fixed pixel widths. Default: <code>false</code>.</td></tr><tr><td><strong>imageRoundPercent</strong></td><td>When <code>true</code>, percentage-based image sizes are rounded to whole numbers. Default: <code>false</code>.</td></tr><tr><td><strong>imageDefaultWidth</strong></td><td>Sets the default width of an image when it is inserted. Setting it to <code>0</code> will not set any width. Default: <code>300</code>.</td></tr><tr><td><strong>imageDefaultAlign</strong></td><td>Sets the default image alignment when inserted. Possible values are <code>left</code>, <code>center</code> and <code>right</code>. Default: <code>center</code>.</td></tr><tr><td><strong>imageDefaultDisplay</strong></td><td>Sets the default display for an inserted image. Possible values are <code>inline</code> and <code>block</code>. Default: <code>block</code>.</td></tr><tr><td><strong>imageDefaultMargin</strong></td><td>Default margin in pixels applied to inserted images. Default: <code>5</code>.</td></tr><tr><td><strong>imageMinWidth</strong></td><td>Minimum width (in pixels) when resizing an image. Default: <code>16</code>.</td></tr><tr><td><strong>imageMaxSize</strong></td><td>Maximum allowed upload size in bytes. Default: <code>10485760</code> (10MB).</td></tr><tr><td><strong>imageAllowedTypes</strong></td><td>Array of allowed image file extensions for uploads. Default: <code>[&#39;jpeg&#39;, &#39;jpg&#39;, &#39;png&#39;, &#39;gif&#39;, &#39;webp&#39;]</code>.</td></tr><tr><td><strong>imageMultipleStyles</strong></td><td>When <code>false</code>, only one style class can be applied to an image at a time. Default: <code>true</code>.</td></tr><tr><td><strong>imageTextNear</strong></td><td>Allows text to wrap next to an inserted image. Default: <code>true</code>.</td></tr><tr><td><strong>imageOutputSize</strong></td><td>When <code>true</code>, image width and height attributes are written into the output HTML. Default: <code>false</code>.</td></tr><tr><td><strong>imageSplitHTML</strong></td><td>When <code>true</code>, the editor will split paragraphs to place block images. Default: <code>false</code>.</td></tr><tr><td><strong>imageAddNewLine</strong></td><td>When <code>true</code>, a new line is automatically added after an inserted image. Default: <code>false</code>.</td></tr><tr><td><strong>imageStyles</strong></td><td>Object mapping CSS class names to style labels available in the image edit popup. Default includes <code>fr-rounded</code>, <code>fr-bordered</code>, <code>fr-shadow</code>.</td></tr></tbody></table></div><h3 id="file-upload-options"><a href="#file-upload-options" class="header-anchor">#</a> File Upload Options</h3><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>fileUpload</strong></td><td>Enables file uploads. Set to <code>false</code> to disable. Default: <code>true</code>.</td></tr><tr><td><strong>fileMaxSize</strong></td><td>Maximum allowed file upload size in bytes. Default: <code>10485760</code> (10MB).</td></tr><tr><td><strong>fileAllowedTypes</strong></td><td>Array of allowed MIME subtypes for uploads, or <code>[&#39;*&#39;]</code> for any. Default: <code>[&#39;*&#39;]</code>.</td></tr></tbody></table></div><h3 id="drag-and-drop"><a href="#drag-and-drop" class="header-anchor">#</a> Drag and Drop</h3><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>dragInline</strong></td><td>When <code>true</code>, dragged content is dropped at the cursor position inline. When <code>false</code>, drag-and-drop inside the editor is disabled. Default: <code>true</code>.</td></tr></tbody></table></div><h3 id="where-to-find-the-full-list"><a href="#where-to-find-the-full-list" class="header-anchor">#</a> Where to find the full list</h3><p>The <code>editorOptions</code> values are passed through to the underlying Froala v2 editor. Every available option, along with its default, is declared at the top of each plugin file under <code>vendor_drm/froala/js/plugins/</code> in the October CMS source — for example <code>image.js</code> for image options and <code>file.js</code> for file upload options.</p><h3 id="example-block-all-image-insertion"><a href="#example-block-all-image-insertion" class="header-anchor">#</a> Example: block all image insertion</h3><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">html_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> richeditor
    <span class="token key atrule">editorOptions</span><span class="token punctuation">:</span>
        <span class="token key atrule">imageUpload</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
        <span class="token key atrule">imagePaste</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
        <span class="token key atrule">imageMove</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,49))])}const y=l(p,[["render",c]]);export{m as __pageData,y as default};
